/* -G8: its small data (the items' 4-byte data that records_items points to, records_get_digimon_func ...) is in
 * .sdata, which only a -G8 file produces. Its data is at the end of the file. */

extern RecordsItem records_items[];
extern u8 records_item_icons[];
extern u16 *records_item_lists[];

s32 records_find_digimon(s32 id);
RecordsItem *records_get_item(s32 i);

s32 records_find_digimon(s32 id) {
    s32 i;

    for (i = 0; i < 0x34; i++) {
        if (records_digimon[i].id == id) {
            return i;
        }
    }
    return -1;
}

RecordsDigimon *records_get_digimon(s32 id) {
    s32 i = records_find_digimon(id);

    if (i >= 0) {
        return &records_digimon[i];
    }
    return NULL;
}

void records_clear_gauges(void) {
    s32 i;

    for (i = 7; i >= 0; i--) {
        records_state.gauges[i] = 0;
    }
}

/* records_items starts at item 1: GCC folds the - 1 into the address (records_items - 0xC, the end of
 * records_item_lists' last list). */
RecordsItem *records_get_item(s32 i) {
    return (i > 0) ? &records_items[i - 1] : NULL;
}

s32 records_get_item_icon(s32 i) {
    return records_item_icons[records_get_item(i)->type];
}

s32 records_is_item_category(s32 i, s32 category) {
    return records_get_item(i)->category == category;
}

/* Copies the IDs in list records_item_lists[arg0 & 0x7FFFFFFF] that gamestate_data.items marks (or, when arg0's top bit is
 * set, that items_equipped marks) to out; returns how many. */
s32 records_list_items(s32 arg0, u16 *out) {
    s32 all = (arg0 >> 31) != 0;
    s32 type = arg0 & 0x7FFFFFFF;
    u16 *list;
    s32 n;

    if (type >= 5) {
        return 0;
    }
    list = records_item_lists[type];
    n = 0;
    while (*list != 0) {
        if (gamestate_data.items[*list] != 0 || (all && gamestate_data.items_equipped[*list] != 0)) {
            *out++ = *list;
            n++;
        }
        list++;
    }
    return n;
}

